     1→import type { IconData } from "@/components/ui/icon-picker";
     2→import i18n from "@/i18n";
     3→
     4→// ─── Navigation DAG ──────────────────────────────────────────────────────────
     5→//
     6→// The navigation structure is a DAG (Directed Acyclic Graph):
     7→//
     8→//   Nodes = BreadcrumbItemDescriptor (entities with id + routePath)
     9→//   Edges = BreadcrumbEdge (transitions between nodes, carrying injected context)
    10→//
    11→// GLOBAL_ROUTE_DESCRIPTORS are the DAG root nodes.
    12→// Items do NOT carry a "kind" field. To resolve an item's descriptor,
    13→// use the edge index: given a parent descriptor and an item id,
    14→// the edge tells you which descriptor the child resolves to.
    15→//
    16→// The breadcrumb stack is a path through this graph.
    17→
    18→// ── Node (Descriptor) ──
    19→
    20→interface BreadcrumbItemDescriptor {
    21→  id: string;
    22→  routePath: string;
    23→  icon: IconData;
    24→  titleKey: string;
    25→  fallbackLabel: string;
    26→  isContainer?: boolean;
    27→}
    28→
    29→// ── Edges ──
    30→
    31→/** Context keys that an edge injects into the child node's meta */
    32→
    33→export type WorkspaceSection =
    34→  | "apps"
    35→  | "chat"
    36→  | "kanban"
    37→  | "cron"
    38→  | "ideas"
    39→  | "agent"
    40→  | "files"
    41→  | "github"
    42→  | "chat-monitor";
    43→
    44→export type SettingsSection =
    45→  | "general"
    46→  | "account"
    47→  | "shortcuts"
    48→  | "notifications"
    49→  | "gateway"
    50→  | "channels"
    51→  | "executors"
    52→  | "model"
    53→  | "agents"
    54→  | "mcp"
    55→  | "skills"
    56→  | "sandbox"
    57→  | "environment"
    58→  | "terminalFonts"
    59→  | "overlay"
    60→  | "voice"
    61→  | "storage"
    62→  | "developer"
    63→  | "about";
    64→
    65→// ─── DesktopLocation (formerly location.ts) ──────────────────────────────────
    66→
    67→type LocationUrlSuffix = {
    68→  search?: string;
    69→  hash?: string;
    70→};
    71→
    72→export type DesktopLocation = (
    73→  | { kind: "workspace-home"; workspaceId: string }
    74→  | { kind: "workspace-apps"; workspaceId: string }
    75→  | {
    76→      kind: "workspace-section";
    77→      workspaceId: string;
    78→      section: WorkspaceSection;
    79→    }
    80→  | { kind: "workspace-agent-detail"; workspaceId: string; agentId: string }
    81→  | {
    82→      kind: "workspace-executor-detail";
    83→      workspaceId: string;
    84→      executorType: string;
    85→    }
    86→  | { kind: "workspace-page"; workspaceId: string; pageSlug: string }
    87→  | {
    88→      kind: "workspace-web";
    89→      workspaceId: string;
    90→      sourcePageSlug?: string;
    91→      webId?: string;
    92→      title: string;
    93→      url: string;
    94→    }
    95→  | {
    96→      kind: "agent-detail";
    97→      agentId: string;
    98→      workspacePath?: string;
    99→    }
   100→  | {
   101→      kind: "executor-detail";
   102→      executorType: string;
   103→      workspacePath?: string;
   104→    }
   105→  | {
   106→      kind: "skill-detail";
   107→      skillId: string;
   108→      agentId: string;
   109→      workspacePath?: string;
   110→    }
   111→  | {
   112→      kind: "mcp-server-detail";
   113→      serverName: string;
   114→      executorType: string;
   115→      workspacePath?: string;
   116→    }
   117→  | {
   118→      kind: "subagent-detail";
   119→      configId: string;
   120→      executorType: string;
   121→      workspacePath?: string;
   122→    }
   123→  | {
   124→      kind: "prompt-detail";
   125→      promptId: string;
   126→      executorType: string;
   127→      workspacePath?: string;
   128→    }
   129→  | {
   130→      kind: "command-detail";
   131→      commandId: string;
   132→      executorType: string;
   133→      workspacePath?: string;
   134→    }
   135→  | { kind: "settings"; section?: SettingsSection }
   136→  | { kind: "documents" }
   137→  | { kind: "device-pair" }
   138→  | { kind: "global-route"; path: string }
   139→) &
   140→  LocationUrlSuffix;
   141→
   142→// ─── View Target & Breadcrumb Types ─────────────────────────────────────────
   143→
   144→export interface ViewTarget {
   145→  key: string;
   146→  location: DesktopLocation;
   147→  canonicalUrl: string;
   148→}
   149→
   150→// ── Runtime Instances ──
   151→
   152→export interface BreadcrumbStackItem {
   153→  id: string;
   154→  label: string;
   155→  icon?: IconData;
   156→  descriptorId?: string;
   157→  sourceNodeId?: string;
   158→  parentNodeId?: string;
   159→  target?: ViewTarget;
   160→  meta?: {
   161→    workspaceId?: string;
   162→    section?: WorkspaceSection;
   163→    routePath?: string;
   164→    pageSlug?: string;
   165→    agentId?: string;
   166→    executorType?: string;
   167→    webId?: string;
   168→    url?: string;
   169→    blockId?: string;
   170→  };
   171→}
   172→
   173→export interface VirtualPageIndexNode {
   174→  id: string;
   175→  /** References a BreadcrumbItemDescriptor.id */
   176→  descriptorId: string;
   177→  label: string;
   178→  icon?: IconData;
   179→  parentId?: string;
   180→  order: number;
   181→  isContainer?: boolean;
   182→  target?: ViewTarget;
   183→  childSource?: {
   184→    type:
   185→      | "static"
   186→      | "workspace-pages"
   187→      | "workspace-agents"
   188→      | "workspace-executors"
   189→      | "page-navigation";
   190→    workspaceId?: string;
   191→    pageSlug?: string;
   192→  };
   193→  contentRef?: {
   194→    pageSlug: string;
   195→    blockId?: string;
   196→  };
   197→}
   198→
   199→// ── Edge Index ──
   200→// Pre-built lookup: given a parent descriptor id, returns valid child descriptor ids.
   201→// Use `getChildDescriptors(parentId)` to query valid transitions.
   202→// Use `resolveItemDescriptor(item, parentDescriptorId)` to find an item's descriptor.
   203→
   204→export interface TabNavigationState {
   205→  location: DesktopLocation;
   206→  breadcrumbStack: BreadcrumbStackItem[];
   207→  activeNodeId?: string;
   208→  activeIndexPath?: string[];
   209→}
   210→
   211→export interface PushPageOptions {
   212→  mode?: "push" | "replace";
   213→  preserveTail?: boolean;
   214→}
   215→
   216→export function buildViewTarget(
   217→  location: DesktopLocation,
   218→  canonicalUrl: string
   219→): ViewTarget {
   220→  return {
   221→    key: canonicalUrl,
   222→    location,
   223→    canonicalUrl,
   224→  };
   225→}
   226→
   227→// ─── Concrete Descriptors ────────────────────────────────────────────────────
   228→// All descriptors extend BreadcrumbItemDescriptor with domain-specific fields.
   229→
   230→export interface WorkspaceSectionDescriptor extends BreadcrumbItemDescriptor {
   231→  section: WorkspaceSection;
   232→}
   233→
   234→export interface SettingsSectionDescriptor extends BreadcrumbItemDescriptor {
   235→  section: SettingsSection;
   236→}
   237→
