   117→export { buildColdStartBreadcrumb, buildBreadcrumbItem, deriveAncestorsFromPrefix, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
   118→export { registry } from "./route-registry";
